  "prediction_basis_card_ids": [
    "C04","C07","C09","C13","C08","C18","C03","C15","C02","C12","C10","C11",
    "C01","C05","C16","C06","C20","C23","C25","C26","C34","C22","C27","C30",
    "C31","C21","C47","C48","C49","C50","C51","C52","C54","C55","C56","C57","C58"
  ],
  "claims": [
    {
      "claim": "The query is a 1272 Da, fully ionized corrinoid/nucleotide-like phosphodiester with logD -3.35, TPSA 460 Å², 11 HBD and 19 HBA; no direct oral bioavailability measurement exists for it.",
      "card_ids": []
    },
    {
      "claim": "L4 corrinoid/B12 records show human oral fractional absorption of cyanocobalamin of only about 1% at doses ≥500 µg and about 5% at 25 µg, with a Caco-2 Papp of 0.1×10^-6 cm/s; these directly relevant records support negligible systemic absorption for the query's corrinoid-nucleotide scaffold.",
      "card_ids": ["C48","C50","C54","C55","C57","C58"]
    },
    {
      "claim": "L4 permeability records for other large/polar molecules (PMPA <0.1% transported, levovirin Papp 0.12×10^-6 cm/s, vancomycin negligible oral absorption, phosphorothioate oligo Papp 2×10^-8 cm/s) reinforce that extreme size and polarity predict very low passive intestinal permeability.",
      "card_ids": ["C47","C49","C51","C52","C56"]
    },
    {
      "claim": "Measurable ileal permeability of hydroxocobalamin does not translate to high oral F in B12 contexts, where absorption remains about 1-5%; it does not outweigh the low-F corrinoid evidence.",
      "card_ids": ["C53","C48","C55"]
    },
    {
      "claim": "L1/L2 records for polar/nucleotide-like molecules are uniformly below 20% in transferable human contexts (ATP 3.2-14.9%, saquinavir 4%, THU 4.1%, gemcitabine ~10%, levovirin ~10%, didanosine 17%, R1479 6-18%, oxybutynin 7%, phlorizin poor/low, NHC poor), and L3 exposure records are for small nucleoside analogs without query-specific F.",
      "card_ids": ["C04","C07","C09","C13","C08","C18","C03","C15","C02","C12","C10","C11","C01","C05","C16","C06","C20","C23","C25","C26","C34","C22","C27","C30","C31","C21"]
    },
    {
      "claim": "The few above-20% values (levovirin rat 29.3%, NHC mouse 36-56%) are rodent data for small ribonucleosides and are not transferable to a 1272 Da corrinoid phosphodiester.",
      "card_ids": ["C28","C32","C33"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C47","C48","C49","C50","C51","C52","C53","C54","C55","C56","C57","C58"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or query-specific permeability/solubility measurement exists; the decision relies on transfer from B12/corrinoid and other polar-molecule records plus physicochemical priors.",
    "B12 absorption involves intrinsic factor and receptor-mediated uptake; the query lacks cobalt and may not engage this pathway, so the exact absorption mechanism and dose dependence are uncertain.",
    "No query-specific formulation, dose, species, or human PK data are available; formulation-dependent absorption cannot be fully excluded.",
    "L4 records are absorption/permeability assays, not systemic F measurements; first-pass, clearance, and efflux contributions remain unmeasured."
  ],
  "decision_summary": "L4 corrinoid/B12 absorption and permeability records (human B12 absorption ~1-5%, Caco-2 Papp 0.1×10^-6 cm/s) and low permeability of other large polar molecules reinforce the prior low-F conclusion; no transferable evidence supports F >= 20% for this 1272 Da fully ionized corrinoid phosphodiester."
}

